void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;

    /* Initialize tile coordinates */
    *p_tx0 = (OPJ_INT32)(p_cp->tx0 + (p_tileno % p_cp->num_tx) * p_cp->tdx);
    *p_tx1 = (OPJ_INT32)((p_cp->tx0 + (p_tileno % p_cp->num_tx + 1) * p_cp->tdx) > p_image->x1 ?
                          p_image->x1 : p_cp->tx0 + (p_tileno % p_cp->num_tx + 1) * p_cp->tdx);

    *p_ty0 = (OPJ_INT32)(p_cp->ty0 + (p_tileno / p_cp->num_tx) * p_cp->tdy);
    *p_ty1 = (OPJ_INT32)((p_cp->ty0 + (p_tileno / p_cp->num_tx + 1) * p_cp->tdy) > p_image->y1 ?
                          p_image->y1 : p_cp->ty0 + (p_tileno / p_cp->num_tx + 1) * p_cp->tdy);

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        const opj_tcp_t *tcp = &p_cp->tcp[p_tileno];
        const opj_tccp_t *tccp = &tcp->tccps[compno];

        for (resno = 1; resno < tccp->numresolution; ++resno) {
            OPJ_UINT32 dx = tccp->dx[resno];
            OPJ_UINT32 dy = tccp->dy[resno];

            if (dx < dx_min || dx_min == 0) {
                dx_min = dx;
            }
            if (dy < dy_min || dy_min == 0) {
                dy_min = dy;
            }
        }

        if (tccp->numresolution > max_res) {
            max_res = tccp->numresolution;
        }
    }

    max_prec = max_res;
    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;

    OPJ_UINT32 max_precision = 0;
    OPJ_UINT32 max_resolutions = 0;
    OPJ_UINT32 min_prec_width = 0;
    OPJ_UINT32 min_prec_height = 0;

    // Calculate tile coordinates
    if (p_cp->tile_offset_x0) {
        *p_tx0 = p_cp->tile_offset_x0[p_tileno];
        *p_tx1 = p_cp->tile_offset_x1[p_tileno];
    } else {
        *p_tx0 = 0;
        *p_tx1 = p_image->x1;
    }

    if (p_cp->tile_offset_y0) {
        *p_ty0 = p_cp->tile_offset_y0[p_tileno];
        *p_ty1 = p_cp->tile_offset_y1[p_tileno];
    } else {
        *p_ty0 = 0;
        *p_ty1 = p_image->y1;
    }

    for (compno = 0; compno < p_image->numcomps; compno++) {
        const opj_tcp_t *tcp = &p_cp->tcp[compno];
        const opj_tccp_t *tccp = &tcp->tccps[0];

        for (resno = 1; resno < tccp->numresolutions; resno++) {
            OPJ_UINT32 dx = tccp->resolutions[resno].dx;
            OPJ_UINT32 dy = tccp->resolutions[resno].dy;

            if (resno > max_resolutions)
                max_resolutions = resno;

            if (dx < min_prec_width || min_prec_width == 0)
                min_prec_width = dx;

            if (dy < min_prec_height || min_prec_height == 0)
                min_prec_height = dy;
        }

        if (tccp->numresolutions > max_precision)
            max_precision = tccp->numresolutions;
    }

    *p_dx_min = min_prec_width;
    *p_dy_min = min_prec_height;
    *p_max_prec = max_precision;
    *p_max_res = max_resolutions;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_precision = 0;
    OPJ_UINT32 max_resolutions = 0;
    OPJ_UINT32 min_dx = p_cp->tx0;
    OPJ_UINT32 min_dy = p_cp->ty0;

    *p_tx0 = 0;
    *p_tx1 = 0;
    *p_ty0 = 0;
    *p_ty1 = 0;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        for (resno = 0; resno < p_cp->max_res; resno++) {
            if (resno > max_resolutions) {
                max_resolutions = resno;
            }
        }
        for (resno = 0; resno < p_cp->max_res; resno++) {
            if (p_cp->enc->tp_on && resno == p_cp->enc->tp_on_res) {
                max_precision++;
            }
        }
    }

    max_resolutions++;
    max_precision++;

    if (p_cp->tx0 <= p_image->x0 || p_cp->ty0 <= p_image->y0) {
        *p_tx0 = p_cp->tx0;
        *p_ty0 = p_cp->ty0;
    } else {
        *p_tx0 = p_image->x0;
        *p_ty0 = p_image->y0;
    }

    *p_tx1 = p_image->x1;
    *p_ty1 = p_image->y1;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        if (min_dx > p_cp->enc->dx[compno])
            min_dx = p_cp->enc->dx[compno];
        if (min_dy > p_cp->enc->dy[compno])
            min_dy = p_cp->enc->dy[compno];
    }

    *p_dx_min = min_dx;
    *p_dy_min = min_dy;
    *p_max_prec = max_precision;
    *p_max_res = max_resolutions;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;
    OPJ_UINT32 num_resolutions;
    OPJ_UINT32 num_components = p_image->numcomps;

    *p_tx0 = 0;
    *p_tx1 = 0;
    *p_ty0 = 0;
    *p_ty1 = 0;

    for (compno = 0; compno < num_components; ++compno) {
        opj_tcp_t *tcp = &p_cp->tcp[compno];
        num_resolutions = tcp->num_resolutions;

        if (num_resolutions > max_res) {
            max_res = num_resolutions;
        }

        for (resno = 0; resno < num_resolutions; ++resno) {
            OPJ_UINT32 dx = tcp->dx[resno];
            OPJ_UINT32 dy = tcp->dy[resno];
            OPJ_UINT32 precno;

            for (precno = 0; precno < tcp->precno_end; ++precno) {
                if (dx < dx_min || dx_min == 0) {
                    dx_min = dx;
                }
                if (dy < dy_min || dy_min == 0) {
                    dy_min = dy;
                }
            }

            if ((resno + 1) > max_prec) {
                max_prec = resno + 1;
            }
        }
    }

    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_ty0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 dx, dy;
    OPJ_UINT32 max_dx;
    OPJ_UINT32 max_dy;

    *p_max_prec = 0;

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        OPJ_UINT32 numres = p_cp->enc_params[compno].numres;
        if (numres > *p_max_prec) {
            *p_max_prec = numres;
        }

        for (resno = 0; resno < numres; ++resno) {
            dx = p_cp->enc_params[compno].resolutions[resno].dx;
            dy = p_cp->enc_params[compno].resolutions[resno].dy;

            if (resno == 0) {
                max_dx = dx;
                max_dy = dy;
            } else {
                if (dx > max_dx) {
                    max_dx = dx;
                }
                if (dy > max_dy) {
                    max_dy = dy;
                }
            }
        }
    }

    *p_dx_min = max_dx;
    *p_dy_min = max_dy;

    *p_max_res = 0;
    for (compno = 0; compno < p_image->numcomps; ++compno) {
        OPJ_UINT32 numres = p_cp->enc_params[compno].numres;
        if (numres > *p_max_res) {
            *p_max_res = numres;
        }
    }

    if (p_cp->tileno == 0) {
        *p_tx0 = 0;
        *p_ty0 = 0;
        *p_tx1 = p_image->x1 - p_image->x0;
        *p_ty1 = p_image->y1 - p_image->y0;
    } else {
        *p_tx0 = (p_tileno % p_cp->tileno) * p_cp->tx_size;
        *p_ty0 = (p_tileno / p_cp->tileno) * p_cp->ty_size;
        *p_tx1 = *p_tx0 + p_cp->tx_size;
        *p_ty1 = *p_ty0 + p_cp->ty_size;

        if (*p_tx1 > (OPJ_INT32)(p_image->x1 - p_image->x0)) {
            *p_tx1 = p_image->x1 - p_image->x0;
        }

        if (*p_ty1 > (OPJ_INT32)(p_image->y1 - p_image->y0)) {
            *p_ty1 = p_image->y1 - p_image->y0;
        }
    }
}
